import glob,re,sys
B={
"S01":("aucun : tout est expliqué ici, même ce qui te paraît évident.","aucun.","hardware, software, carte mère, processeur, mémoire vive, stockage (HDD, SSD), BIOS/UEFI, bus, pilote. Les sigles sont dans le [glossaire](../../ressources/glossaire.md)."),
"S02":("la fiche d'identité d'un poste (S01) : composants, mémoires, stockage.","bit, octet, processeur, mémoire vive, SSD.","préfixes (kilo, méga, Kio, Mio), conversions, débit et temps de transfert, PowerShell et CMD."),
"S03":("lire les caractéristiques d'un poste et convertir les unités (S01, S02).","processeur, mémoire vive, SSD, fréquence, octet.","cœur, fréquence, benchmark, RAID, serveur et poste, dimensionnement. Le RAID 0, 1 et 5 sont à connaître ; les autres niveaux sont signalés <span class=\"technique\">notion technique</span>."),
"S04":("composants et unités (S01 à S03).","BIOS, UEFI, pilote, processeur, octet.","système d'exploitation, noyau, démarrage, MBR et GPT, 32/64 bits, licences, mises à jour, outils d'observation de Windows."),
"S05":("ce qu'est un système d'exploitation, ses licences et ses outils (S04).","noyau, système d'exploitation, logiciel libre, licence.","distribution, environnement de bureau, GPL, familles de distributions, comparaison Windows/Linux. `sudo` et `root` sont seulement **présentés** ; tu les utiliseras vraiment en S08."),
"S06":("composants, système d'exploitation, stockage (S01 à S05).","processeur, mémoire vive, noyau, système d'exploitation, ISO.","machine virtuelle, hôte et invité, hyperviseur, émulation, conteneur (idée seulement : détaillé en S11), création d'une VM."),
"S07":("créer et démarrer une VM dans VirtualBox (S06) ; savoir ce qu'est une adresse IP : voir la fiche [minimum réseau](../../ressources/minimum-reseau.md).","hôte, invité, hyperviseur, ISO.","modes réseau de VirtualBox, instantané (snapshot), chaîne de disques, Guest Additions, stockage d'une VM. Les notions de réseau (NAT, DHCP, adresse IP) seront **vues en cours de réseau** : ici, tu retiens seulement ce qui sert à connecter une VM."),
"S08":("importer et démarrer une VM Debian (S06, S07) ; lire une arborescence de dossiers comme sur Windows.","shell, bash, noyau, `root` et `sudo` (présentés en S05).","terminal et prompt, chemins absolu et relatif, commandes de navigation et de gestion de fichiers, redirection et tube, `sudo`, noms avec espaces. **Session chargée, soyez concentrés** : c'est la base de tout le reste."),
"S09":("naviguer et gérer des fichiers dans le terminal (S08), utiliser `sudo`.","chemin absolu, chemin relatif, `sudo`, `root`, redirection.","utilisateur, groupe, propriétaire, droits `rwx` et leur notation en chiffres, `chmod`, `chown`, lien symbolique."),
"S10":("commandes de base, droits et `sudo` (S08, S09).","tube, redirection, droits, chemin, `sudo`.","paquet et gestionnaire de paquets, script, variable, condition, boucle, code de retour."),
"S11":("terminal Linux (S08 à S10) ; ce qu'est une VM (S06) ; port et adresse IP : voir la fiche [minimum réseau](../../ressources/minimum-reseau.md).","machine virtuelle, noyau, conteneur (cité en S06), `sudo`, paquet.","image, conteneur, registre, cycle de vie, port publié, variable d'environnement, volume, réseau Docker. **Session chargée, soyez concentrés** : prends le temps de remplir ta fiche de commandes."),
"S12":("fiche d'identité d'un poste (S02) ; terminal Linux (S08 à S10).","inventaire d'un poste, composants.","patrimoine, inventaire, fiche d'inventaire, agent, méthodes manuelle et automatisée, qualité des données, données personnelles et RGPD."),
"S13":("virtualisation (S06, S07), terminal et paquets (S08 à S10), inventaire (S12).","agent, inventaire, CMDB, paquet, VM, instantané.","GLPI, base de données, serveur web, agent GLPI, diagnostic d'un poste qui ne remonte pas."),
"S14":("GLPI installé et un poste inventorié (S13) ; CMDB et CI (S12).","GLPI, agent, CMDB, élément de configuration (CI).","entité, profil, groupe, logiciel et licence dans GLPI, rapports, sécurité et données personnelles."),
"S15":("GLPI configuré (S13, S14) ; CMDB (S12).","GLPI, CMDB, entité, profil.","ITIL, service, incident, problème, demande, changement, impact, urgence, priorité, SLA, centre de services, ticket. **Session chargée, soyez concentrés** : beaucoup de vocabulaire nouveau, un tableau récapitulatif te sert de repère."),
"S16":("tickets, priorités, SLA (S15) ; CMDB (S12).","incident, ticket, impact, urgence, priorité.","cycle de vie d'un incident, méthode de diagnostic, corrélation, base de connaissances, supervision. Les mots « ping », « port » et « DNS » sont dans la fiche [minimum réseau](../../ressources/minimum-reseau.md)."),
"S17":("tickets, priorités et SLA (S15) ; diagnostic (S16) ; CMDB (S12).","service, SLA, ticket, priorité, supervision, MTTR.","catalogue de services, SLA, OLA, disponibilité, incident majeur, du service aux éléments de configuration, présence en ligne. **Session chargée, soyez concentrés.**"),
"S18":("VM et réseaux de VirtualBox (S06, S07) ; terminal (S08 à S10) ; cycle de vie des équipements (S12) ; la fiche [minimum réseau](../../ressources/minimum-reseau.md).","DHCP, adresse IP, instantané, VM.","clonage, démarrage par le réseau (PXE), image maître, identité d'une machine après clonage."),
"S19":("scripts Bash (S10) ; conteneurs (S11) ; changements (S15, S17).","script, variable, boucle, code de retour, utilisateur, droits.","automatisation, script fiable, création de comptes en masse, `cron`, SSH et clés, annuaire. **Session chargée, soyez concentrés** : les passages marqués <span class=\"technique\">notion technique</span> sont facultatifs."),
"S20":("scripts et `cron` (S10, S19) ; GLPI et sa base de données (S13, S14).","sauvegarde, instantané, base de données, `cron`, SSH.","RPO, RTO, règle 3-2-1, types de sauvegarde, différence avec instantané et réplication, empreinte, chiffrement."),
"S21":("les séances S11 à S20 et leurs comptes rendus.","tout le vocabulaire du semestre : voir le [glossaire](../../ressources/glossaire.md).","fiche de réalisation, tableau de synthèse, portfolio, entretien d'explicitation, recette. **Session chargée, soyez concentrés** : la rédaction demande du temps, commence dès l'étape A."),
}
for f in sorted(glob.glob("docs/semestre-*/S*/01-cours.md")):
    s=f.split("/")[-2][:3]; pre,vus,ici=B[s]
    s_=open(f,encoding="utf-8").read()
    if "Ce que tu dois savoir déjà" in s_: continue
    blk=f"> [!NOTE] Ce que tu dois savoir déjà\n> - **Prérequis :** {pre}\n> - **Mots déjà vus :** {vus}\n> - **Expliqués dans ce cours :** {ici}\n\n"
    m="## À la fin de ce cours, tu sauras"
    assert m in s_,f
    open(f,"w",encoding="utf-8").write(s_.replace(m,blk+m,1))
